css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; overflow: hidden; border-radius: 8px; }
.loader .face { position: absolute; inset: 0; border-radius: 8px; background: linear-gradient(color-mix(in srgb, #fff 14%, var(--accent)), var(--accent)); }
.loader .screen { position: absolute; left: 12%; right: 12%; top: 8%; height: 32%; border-radius: 5px; background: color-mix(in srgb, #0f172a 72%, transparent); overflow: hidden; }
.loader .screen::after { content: ''; position: absolute; left: 8%; right: 8%; top: 60%; height: 14%; border-radius: 3px; background: color-mix(in srgb, var(--accent-2) 30%, transparent); box-shadow: inset 0 0 0 1px var(--accent-2); }
.loader .screen::before { content: ''; position: absolute; left: 8%; top: 60%; width: 0; height: 14%; border-radius: 3px; background: var(--accent-2); z-index: 1; animation: atm-progress calc(var(--loader-speed) * 3) linear infinite; }
.loader .slot { position: absolute; left: 16%; right: 16%; top: 52%; height: 6%; border-radius: 3px; background: color-mix(in srgb, #0f172a 80%, transparent); }
.loader span { position: absolute; left: 20%; width: 60%; height: 11%; border-radius: 3px; background: linear-gradient(90deg, color-mix(in srgb, #fff 40%, var(--accent-2)), var(--accent-2)); box-shadow: 0 2px 4px color-mix(in srgb, #000 25%, transparent); opacity: 0; animation: atm-note calc(var(--loader-speed) * 3) cubic-bezier(.4, 0, .4, 1) infinite; }
.loader span:nth-of-type(1) { animation-delay: calc(var(--loader-speed) * 1.2); }
.loader span:nth-of-type(2) { animation-delay: calc(var(--loader-speed) * 1.6); }
.loader span:nth-of-type(3) { animation-delay: calc(var(--loader-speed) * 2); }
@keyframes atm-progress { 0%, 8% { width: 0; } 62%, 100% { width: 84%; } }
@keyframes atm-note { 0% { opacity: 0; top: 52%; transform: scaleY(.4); } 12% { opacity: 1; } 60% { opacity: 1; top: 76%; transform: scaleY(1); } 100% { opacity: 0; top: 88%; transform: scaleY(1); } }
